import{_ as r,o as a,c as e,ag as d}from"./chunks/framework.Aev9KvMf.js";const c=JSON.parse('{"title":"技能提升补贴 · 考出证能领的政府钱","description":"失业保险技能提升补贴官方申领教程：目录内证书按等级最高 2000 元级补贴，线上申领入口与条件，防\\"机构代领\\"骗局。","frontmatter":{"title":"技能提升补贴 · 考出证能领的政府钱","issuer":"人力资源社会保障部","source_tier":"一级来源","version":"—","published":"—","source_url":"https://si.12333.gov.cn/","status":"现行服务","tags":["官方查询","技能补贴","考证","社保","家庭财务"],"type":"查询页","reviewed":false,"description":"失业保险技能提升补贴官方申领教程：目录内证书按等级最高 2000 元级补贴，线上申领入口与条件，防\\"机构代领\\"骗局。"},"headers":[],"relativePath":"query/skill-subsidy.md","filePath":"query/skill-subsidy.md"}'),o={name:"query/skill-subsidy.md"};function s(h,t,l,n,i,u){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="技能提升补贴-·-考出证能领的政府钱" tabindex="-1">技能提升补贴 · 考出证能领的政府钱 <a class="header-anchor" href="#技能提升补贴-·-考出证能领的政府钱" aria-label="Permalink to &quot;技能提升补贴 · 考出证能领的政府钱&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 会话信息整理（国家社保平台入口已核验可达）；补贴标准与条件<strong>各地有差异</strong>，以当地规定和 12333 答复为准。</p></div><blockquote><p><strong>官方入口</strong>：<a href="https://si.12333.gov.cn/" target="_blank" rel="noreferrer">国家社会保险公共服务平台</a>（&quot;职业技能提升补贴申领&quot;模块）、各地人社 App/经办机构；咨询 12333。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>企业在职职工依法缴纳<strong>失业保险</strong>、考取**《国家职业资格目录》内<strong>的证书（或职业技能等级证书）的，可申领</strong>技能提升补贴**：国家基准为初级（五级）1000 元、中级（四级）1500 元、高级（三级）2000 元，<strong>各地可上浮</strong>（待核验）。这是&quot;考证防坑&quot;篇的另一半：目录内的证考下来，政府真给钱。</p><h2 id="申领条件-待核验" tabindex="-1">申领条件（待核验） <a class="header-anchor" href="#申领条件-待核验" aria-label="Permalink to &quot;申领条件（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条件</th><th>说明</th></tr></thead><tbody><tr><td>参保身份</td><td>企业在职职工（缴纳失业保险累计 <strong>12 个月</strong>及以上；部分地区放宽，含领取失业保险金人员）</td></tr><tr><td>证书范围</td><td><a href="/SageRelay/query/cert-search.html">国家职业资格目录</a>内证书，或官方可查的职业技能等级证书</td></tr><tr><td>时限</td><td><strong>证书核发之日起 12 个月内</strong>申领（待核验）</td></tr><tr><td>次数</td><td>同一证书只能享受一次；每人每年享受补贴次数有上限（待核验）</td></tr></tbody></table><h2 id="_30-秒申领步骤-待核验" tabindex="-1">30 秒申领步骤（待核验） <a class="header-anchor" href="#_30-秒申领步骤-待核验" aria-label="Permalink to &quot;30 秒申领步骤（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th></tr></thead><tbody><tr><td>1</td><td>先确认证书可查：<a href="/SageRelay/query/cert-search.html">证书查询</a>能查到</td></tr><tr><td>2</td><td>登录<a href="https://si.12333.gov.cn/" target="_blank" rel="noreferrer">国家社保平台</a> → &quot;职业技能提升补贴申领&quot;，或用当地人社 App/小程序</td></tr><tr><td>3</td><td>填证书编号，系统联网核验后按当地标准发放（一般发放至社保卡金融账户或银行卡）</td></tr><tr><td>4</td><td>线上办不了的：带身份证、证书到参保地失业保险经办机构办理</td></tr></tbody></table><h2 id="结果怎么读" tabindex="-1">结果怎么读 <a class="header-anchor" href="#结果怎么读" aria-label="Permalink to &quot;结果怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到什么</th><th>说明</th></tr></thead><tbody><tr><td>审核通过、补贴到账</td><td>正常（<a href="https://si.12333.gov.cn/" target="_blank" rel="noreferrer">社保平台</a>）</td></tr><tr><td>提示&quot;不符合条件&quot;</td><td>多为缴费月数不足、证书不在目录/超时限——先按提示对照，再问 12333</td></tr><tr><td>当地无此模块</td><td>部分地区走线下经办窗口，电话 12333 确认</td></tr></tbody></table><h2 id="避坑要点" tabindex="-1">避坑要点 <a class="header-anchor" href="#避坑要点" aria-label="Permalink to &quot;避坑要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方事实</th></tr></thead><tbody><tr><td>&quot;报我们班考完，补贴打到我们卡里再给你&quot;</td><td>补贴<strong>直接发给个人</strong>，不经过任何机构——要求代收的都是坑</td></tr><tr><td>&quot;包考包补贴，等于免费拿证&quot;</td><td>补贴有条件（参保、目录内、时限），先查自己是否符合，别为补贴反向买课</td></tr><tr><td>【本站提示】没有失业保险参保记录的（灵活就业、城乡居民）一般不适用本补贴——别信&quot;人人可领&quot;</td><td>—</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>证书核验与目录：<a href="/SageRelay/query/cert-search.html">考证防坑 · 证书查询</a></li><li>政策咨询与申领：<a href="/SageRelay/query/si-12333.html">国家社保平台</a> · 12333</li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>政策</td><td>失业保险技能提升补贴（人社部发〔2017〕40 号建立，后续文件延续调整，<strong>待核验</strong>）</td></tr><tr><td>入口</td><td><a href="https://si.12333.gov.cn/" target="_blank" rel="noreferrer">si.12333.gov.cn</a>（已核验可达）· 12333</td></tr></tbody></table>',17)])])}const q=r(o,[["render",s]]);export{c as __pageData,q as default};
